//go:build ignore
package main
import("context";"encoding/json";"fmt";"os";"path/filepath";"time";"github.com/jackc/pgx/v5")
func main(){ctx,cancel:=context.WithTimeout(context.Background(),30*time.Second);defer cancel();cfg,e:=pgx.ParseConfig(os.Getenv("DATABASE_URL"));if e!=nil{panic("config")};cfg.RuntimeParams["default_transaction_read_only"]="on";c,e:=pgx.ConnectConfig(ctx,cfg);if e!=nil{panic("db")};defer c.Close(ctx);tx,e:=c.BeginTx(ctx,pgx.TxOptions{IsoLevel:pgx.RepeatableRead,AccessMode:pgx.ReadOnly});if e!=nil{panic("tx")};defer tx.Rollback(ctx)
const round="replay_f2973aad4da55cb7fe38208bc45df82f"
qs:=map[string]string{
"batches":`SELECT row_to_json(x) FROM(SELECT source,status,stage,error_code,count(*) batches,sum(change_count) changes FROM control_batches WHERE round_id=$1 GROUP BY source,status,stage,error_code ORDER BY source,status)x`,
"items":`SELECT row_to_json(x) FROM(SELECT CASE WHEN record->>'resource'='course_change_group' THEN 'processing_group' WHEN item_id='item_'||substr(encode(sha256(convert_to(batch_id||'/'||change_id,'UTF8')),'hex'),1,32) THEN 'source_item' ELSE 'derived_item' END kind,status,count(*) count FROM control_items WHERE round_id=$1 GROUP BY kind,status ORDER BY kind,status)x`,
"artifacts":`SELECT row_to_json(x) FROM(SELECT type,count(*) count FROM control_artifacts WHERE round_id=$1 GROUP BY type)x`,
"run_errors":`SELECT row_to_json(x) FROM(SELECT a.config->>'agent_type' role,r.state,coalesce(r.record->>'error_code','') error,count(*) runs FROM control_runs r JOIN control_batches b ON b.id=r.batch_id LEFT JOIN agent_instances a ON a.agent_id=r.agent_id WHERE b.round_id=$1 GROUP BY a.config->>'agent_type',r.state,r.record->>'error_code' ORDER BY a.config->>'agent_type',r.state)x`,
"usage":`SELECT row_to_json(x) FROM(SELECT a.config->>'agent_type' role,count(*) runs,sum((ar.record->>'model_calls')::integer) model_calls,sum((ar.record->>'tool_calls')::integer) tool_calls,sum((ar.record->'usage'->>'prompt_tokens')::bigint) prompt_tokens,sum((ar.record->'usage'->>'completion_tokens')::bigint) completion_tokens FROM agent_runs ar JOIN control_runs r ON r.run_id=ar.run_id JOIN control_batches b ON b.id=r.batch_id LEFT JOIN agent_instances a ON a.agent_id=ar.agent_id WHERE b.round_id=$1 GROUP BY a.config->>'agent_type')x`,
}
report:=map[string]any{"round_id":round,"read_only":true,"at":time.Now().UTC()};for name,q:=range qs{rows,e:=tx.Query(ctx,q,round);if e!=nil{panic("query "+name)};out:=[]json.RawMessage{};for rows.Next(){var raw []byte;if e=rows.Scan(&raw);e!=nil{panic("scan")};out=append(out,raw)};rows.Close();if rows.Err()!=nil{panic("rows")};report[name]=out};raw,_:=json.MarshalIndent(report,"","  ");p:=filepath.Join("../.build/backend-flash-full-20261115","audit-latest.private.json");if e=os.WriteFile(p,raw,0600);e!=nil{panic("save")};fmt.Println(string(raw))}
